contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: send some value and set unlock time, then check balances
    function run(uint unlockTime, uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);
        // read balance recorded in c for this contract before the call
        uint beforeRecorded = c.Acc(address(this)).balance;
        uint beforeAddrBal = address(c).balance;

        // perform the Put call sending sendAmount wei
        bool reverted = false;
        try c.Put{value: sendAmount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterRecorded = c.Acc(address(this)).balance;
        uint afterAddrBal = address(c).balance;

        // General rule:
        // If the call did not revert then: afterRecorded >= beforeRecorded and
        // afterRecorded - beforeRecorded <= sendAmount and address(c).balance increased exactly by sendAmount.
        // If the call reverted then nothing observable about c changed (balances equal).
        assert(
            (!reverted && afterRecorded >= beforeRecorded && (afterRecorded - beforeRecorded) <= sendAmount && afterAddrBal == beforeAddrBal + sendAmount)
            || (reverted && afterRecorded == beforeRecorded && afterAddrBal == beforeAddrBal)
        );
    }

    receive() external payable {}
}

