contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put then optionally Collect and check that the combined observable funds
    // (address(c).balance + Acc(this).balance) change exactly by the externally supplied value
    // minus any amount successfully collected out to this contract.

    // input params:
    // putAmount: amount of wei to send to Put (may be zero)
    // unlockTime: parameter for Put
    // collectAmount: amount to attempt to collect
    // doCollect: whether to attempt Collect after Put
    function run(uint putAmount, uint unlockTime, uint collectAmount, bool doCollect) public payable {
        require(address(this).balance >= putAmount + 1 wei || address(this).balance >= putAmount, true);
        // observe initial values
        uint beforeContractBal = address(c).balance;
        C.Holder memory beforeHolder = c.Acc(address(this));
        uint beforeRecorded = beforeHolder.balance;

        // Perform Put with value putAmount
        // ensure this contract has enough balance to send putAmount
        if (putAmount > 0) {
            // call Put with value
            c.Put{value: putAmount}(unlockTime);
        } else {
            c.Put{value: 0}(unlockTime);
        }

        // after Put, observe
        uint midContractBal = address(c).balance;
        C.Holder memory midHolder = c.Acc(address(this));
        uint midRecorded = midHolder.balance;

        bool collectReverted = false;
        if (doCollect) {
            // Attempt Collect; it may revert or succeed. Catch revert flag.
            try c.Collect{value: 0}(collectAmount) {
                collectReverted = false;
            } catch {
                collectReverted = true;
            }
        }

        // final observations
        uint afterContractBal = address(c).balance;
        C.Holder memory afterHolder = c.Acc(address(this));
        uint afterRecorded = afterHolder.balance;

        // Now assert the invariant relating observed balances:
        // 1) midContractBal == beforeContractBal + putAmount
        //    and midRecorded == beforeRecorded + putAmount
        // 2) If Collect succeeded (doCollect && !collectReverted) then:
        //      - afterRecorded == midRecorded - collectAmount
        //      - afterContractBal == midContractBal - collectAmount
        //      (Collect only sends when sufficient balance and unlocked, but visibility limited; we assert observed effects when call did not revert.)
        // 3) If Collect reverted or not attempted, recorded and contract balances remain as after Put.

        assert(
            // Put effect holds
            midContractBal == beforeContractBal + putAmount && midRecorded == beforeRecorded + putAmount
            && (
                // If we attempted collect and it succeeded
                (doCollect && !collectReverted) ? (
                    // then both recorded and contract balances decreased by exactly collectAmount
                    afterRecorded + collectAmount == midRecorded && afterContractBal + collectAmount == midContractBal
                ) : (
                    // else no change after Put
                    afterRecorded == midRecorded && afterContractBal == midContractBal
                )
            )
        );
    }

    // Receive to accept Ether from C during Collect
    receive() external payable {}
}

