    // and amountToCollect requested in Collect. This function is payable so it can send ETH to c.
    function run(uint amountToPut, uint unlockTime, uint amountToCollect) public payable {
        require(address(this).balance >= amountToPut, "insufficient balance to fund Put");
        // Before any calls, read observable state for msg.sender (which will be this contract as deployer)
        C.Holder memory beforeAcc = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform Put: send amountToPut wei and set unlockTime
        c.Put{value: amountToPut}(unlockTime);

        // Read state immediately after Put
        C.Holder memory afterPutAcc = c.Acc(address(this));
        uint afterPutContractBal = address(c).balance;

        // Now attempt Collect: it may revert. Capture whether it reverted and any state after.
        bool collectReverted;
        try c.Collect{value: 0}(amountToCollect) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        C.Holder memory afterCollectAcc = c.Acc(address(this));
        uint afterCollectContractBal = address(c).balance;

        // General rule to assert:
        // 1) Put must not decrease the recorded balance for this holder and must increase contract balance accordingly
        // 2) Collect, if it did not revert, must not increase the holder's recorded balance and contract balance must drop by exactly amountToCollect
        // 3) If Collect reverted, the holder balance and contract balance remain as after Put
        assert(
            // Put monotonic: recorded balance afterPut >= beforeAcc.balance
            (afterPutAcc.balance >= beforeAcc.balance)
            // contract received the funds (non-decreasing by at least amountToPut)
            && (afterPutContractBal >= beforeContractBal)
            // After Collect either succeeded or reverted:
