                    // when Collect succeeded, recorded balance did not increase (it should decrease or stay same)
                    afterCollectAcc.balance <= afterPutAcc.balance
                    // contract balance decreased by exactly amountToCollect when Collect succeeded
                    && (afterCollectContractBal + amountToCollect == afterPutContractBal)
                )
            )
        );
    }

    // receive to accept Ether if needed
    receive() external payable {}
}

